from __future__ import annotations

from typing import Any


def compile_neo_run_js(data: dict[str, Any], *, base_url: str) -> str:
    """Compile beats into a BrowserOS neo `run` script body (top-level await).

    Matches the neo `run` tool SDK: browser.open, page.goto, waitForText,
    waitForTime. Returns { ok, log, pageId }.
    """
    product = data.get("product") or "demo"
    lines = [
        "// Generated by demo-studio — edit the beat file, not this script.",
        f"// product={product}",
        f"const base = (typeof inputs !== 'undefined' && inputs.baseUrl ? inputs.baseUrl : {base_url!r}).replace(/\\/$/, '');",
        "const log = [];",
        "const fail = (msg) => { throw new Error(msg); };",
        "const page = await browser.open(base + '/');",
        "log.push({ event: 'open', url: base + '/' });",
        "",
    ]

    for beat in data.get("beats") or []:
        bid = beat.get("id")
        lines.append(f"// --- beat {bid} ---")
        lines.append(f"log.push({{ beat: {bid!r}, event: 'start' }});")
        for action in beat.get("actions") or []:
            atype = action.get("type")
            if atype == "note":
                lines.append(f"log.push({{ beat: {bid!r}, note: {action.get('text', '')!r} }});")
            elif atype == "navigate":
                path = action.get("path") or action.get("url") or "/"
                if str(path).startswith("http"):
                    lines.append(f"await page.goto({path!r});")
                else:
                    if not str(path).startswith("/"):
                        path = "/" + path
                    lines.append(f"await page.goto(base + {path!r});")
            elif atype == "wait_ms":
                ms = int(action.get("ms") or 0)
                lines.append(f"await page.waitForTime({ms});")
            elif atype == "wait_text":
                text = action.get("text") or ""
                lines.append(f"{{ const w = await page.waitForText({text!r});")
                lines.append(
                    f"  if (!w.matched) fail('wait_text miss in beat {bid}: ' + {text!r}); }}"
                )
            elif atype == "click_text":
                text = action.get("text") or ""
                lines.append("{")
                lines.append("  const snap = await page.snapshot({ mode: 'interactive' });")
                lines.append(
                    f"  const line = String(snap.text || '').split('\\n').find(l => l.includes({text!r}));"
                )
                lines.append(
                    f"  const m = line && line.match(/\\[ref=(e\\d+)\\]/);"
                )
                lines.append(
                    f"  if (!m) fail('click_text miss in beat {bid}: ' + {text!r});"
                )
                lines.append("  await page.click(m[1]);")
                lines.append("}")
            elif atype == "snapshot":
                lines.append("await page.snapshot({ mode: 'interactive' });")
            else:
                lines.append(f"log.push({{ beat: {bid!r}, skippedAction: {atype!r} }});")

        for assertion in beat.get("assert") or []:
            at = assertion.get("type")
            if at == "url_contains":
                val = assertion.get("value") or ""
                lines.append("{")
                lines.append("  const info = page.info ? await page.info() : { url: '' };")
                lines.append("  const u = String(info.url || '');")
                lines.append(
                    f"  if (!u.includes({val!r})) fail('url_contains failed in {bid}: ' + u);"
                )
                lines.append("}")
            elif at == "page_has_text":
                val = assertion.get("value") or ""
                lines.append(f"{{ const w = await page.waitForText({val!r});")
                lines.append(
                    f"  if (!w.matched) fail('page_has_text miss in {bid}: ' + {val!r}); }}"
                )
            elif at == "http_ok":
                lines.append(
                    f"log.push({{ beat: {bid!r}, assert: 'http_ok deferred-to-python' }});"
                )

        pause = int(beat.get("pause_ms") or 500)
        if pause:
            lines.append(f"await page.waitForTime({pause});")
        lines.append(f"log.push({{ beat: {bid!r}, event: 'end' }});")
        lines.append("")

    lines.extend(
        [
            "return { ok: true, log, pageId: page.id };",
            "",
        ]
    )
    return "\n".join(lines)
